import sys; sys.path.insert(0,'.')
from helpers import *
from scipy.special import erf as serf
D=np.load('base_feats.npz'); y=D['y']
c11=D['cls11'].astype(np.float64); m11=D['mean11'].astype(np.float64)
T=np.eye(8)[y]
gelu=lambda u: 0.5*u*(1+serf(u/np.sqrt(2)))
x=c11+2*m11; xc=x-x.mean(1,keepdims=True); n=xc/xc.std(1,keepdims=True)
Z=(n-n.mean(0))/(n.std(0)+1e-6); G=Z@Z.T/768
def mkfolds(seed,k):
    rng=np.random.default_rng(seed); f=np.zeros(len(y),int)
    for c in range(8):
        idx=np.where(y==c)[0]; rng.shuffle(idx); f[idx]=np.arange(len(idx))%k
    return f
def feat_cv(fn, lam, folds):
    pred=np.zeros(len(y),int)
    for f in range(folds.max()+1):
        tr=folds!=f; P=fn(G[:,tr]); Ptr=P[tr]; pm=Ptr.mean(0); A=Ptr-pm
        a=np.linalg.solve(A@A.T+lam*np.eye(len(A)),T[tr]-T[tr].mean(0))
        pred[~tr]=np.argmax((P[~tr]-pm)@(A.T@a),1)
    return (pred==y).mean()
# linear baseline for same folds
def lin_cv(folds):
    X=np.hstack([c11,m11]); return cv(X,y,folds,ridge_fit,100)[0]
for seed,k in [(11,5),(12,10)]:
    fo=mkfolds(seed,k)
    print('seed',seed,'k',k,'linear concat',round(lin_cv(fo),4))
    for beta in [0.75,1.0,1.25]:
        print('  beta',beta,[round(feat_cv(lambda g,b=beta: gelu(b*g),l,fo),4) for l in [0.003,0.01,0.03]],flush=True)
